-- The simulated payment is gone: an Order is placed straight from the Cart. Its idempotency key is a
-- request id generated by the client for each placement, which replaces the Payment attempt id.
ALTER TABLE orders RENAME COLUMN payment_attempt_id TO request_id;
ALTER TABLE orders RENAME CONSTRAINT orders_payment_attempt_id_unique TO orders_request_id_unique;

DROP TABLE payment_attempt_items;
DROP TABLE payment_attempts;
DROP TABLE stock_reservations;
